-- Generated by svetra 0.6.0 from svetra.yaml (revision 0ea4f5331c78). Do not edit.

-- Tables
create table "public"."note" (
  "id" uuid primary key default gen_random_uuid(),
  "owner" uuid not null,
  "body" text not null
);

-- Foreign keys
alter table "public"."note" add constraint "note_owner_fkey" foreign key ("owner") references "auth"."users" ("id");

-- Indexes
create index "note_owner_idx" on "public"."note" ("owner");

-- Access
alter table "public"."note" enable row level security;

-- Policies
create policy "own_notes_select" on "public"."note"
  for select to authenticated
  using ("owner" = (select auth.uid()));

create policy "own_notes_insert" on "public"."note"
  for insert to authenticated
  with check ("owner" = (select auth.uid()));

create policy "own_notes_update" on "public"."note"
  for update to authenticated
  using ("owner" = (select auth.uid()))
  with check ("owner" = (select auth.uid()));

create policy "own_notes_delete" on "public"."note"
  for delete to authenticated
  using ("owner" = (select auth.uid()));

